50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const HIGH_ENCHANTMENT_LEVEL = 5;
54	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** Modifiers are expressed as an amount to add, never as a factor to multiply
68	 *  by, so that they stay additive against their base and so that the integer
69	 *  numerator keeps float artifacts out of the final rounding
70	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
71	const percentOf = (amount: number, percent: number): number =>
72	  (amount * percent) / 100;
73	
74	/** Rounds up — premiums round in the MHPCO's favour. */
75	const roundPremium = (amount: number): number => Math.ceil(amount);
76	
77	const COMPONENT_BLOCK_SIZE = 3;
78	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
79	
80	const COMPONENT_TYPES = ["rune", "moonstone"];
81	
82	const isComponent = (item: Item): boolean =>
83	  COMPONENT_TYPES.includes(item.type);
84	
85	const itemBasePremium = (item: Item): number =>
86	  BASE_PREMIUM_BY_TYPE[item.type];
87	
88	const countByType = (items: Item[]): Map<string, number> => {
89	  const counts = new Map<string, number>();
90	  for (const item of items) {
91	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
92	  }
93	  return counts;
94	};
95	
96	/** A block is exactly three alike components, priced as a unit rather than
97	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
98	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
99	  count === COMPONENT_BLOCK_SIZE
100	    ? COMPONENT_BLOCK_BASE_PREMIUM
101	    : count * BASE_PREMIUM_BY_TYPE[type];
102	
103	const sum = (amounts: number[]): number =>
104	  amounts.reduce((total, amount) => total + amount, 0);
105	
106	const policyBasePremium = (items: Item[]): number => {
107	  const mainItems = items.filter((item) => !isComponent(item));
108	  const componentGroups = [...countByType(items.filter(isComponent))];
109	
110	  return (
111	    sum(mainItems.map(itemBasePremium)) +
112	    sum(componentGroups.map(componentGroupBasePremium))
113	  );
114	};
115	
116	interface SurchargeRule {
117	  appliesTo: (item: Item) => boolean;
118	  percent: number;
119	}
120	
121	/** Every item-scoped surcharge, as a rule that either applies to an item or
122	 *  does not. Applicable rules stack. */
123	const ITEM_SURCHARGE_RULES: SurchargeRule[] = [
124	  {
125	    appliesTo: (item) => item.cursed === true,
126	    percent: CURSE_SURCHARGE_PERCENT,
127	  },
128	  {
129	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
130	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
131	  },
132	];
133	
134	/** Item-scoped surcharges apply to the affected item's own base premium,
135	 *  not to the policy total. */
136	const itemSurchargeAmount = (item: Item): number =>
137	  sum(
138	    ITEM_SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
139	      percentOf(itemBasePremium(item), rule.percent),
140	    ),
141	  );
142	
143	const quote = (items: Item[], customer: Customer): QuoteResult => {
144	  const basePremium = policyBasePremium(items);
145	  // Every modifier is an amount added to the base premium, not a factor
146	  // compounded onto a running total: item-scoped modifiers take a percentage
147	  // of their own item's base premium, policy-wide ones take a percentage of
148	  // the policy base premium.
149	  const loyaltyDiscount =
150	    customer.yearsWithMHPCO >= LOYALTY_YEARS
151	      ? -percentOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
152	      : 0;
153	  const modifierAmounts = [
154	    ...items.map(itemSurchargeAmount),
155	    loyaltyDiscount,
156	    percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT),
157	  ];
158	  // The processing fee is added last, after all percentage modifiers.
159	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
160	  return { premium: roundPremium(premium) };
161	};
162	
163	const runStep = (step: Step, customer: Customer): StepResult => {
164	  if (step.op === "quote") return quote(step.items, customer);
165	  throw new Error(`Unsupported step: ${step.op}`);
166	};
167	
168	export const runScenario = (scenario: Scenario): ScenarioResult => {
169	  const results = scenario.steps.map((step) =>
170	    runStep(step, scenario.customer),
171	  );
172	  return { results };
173	};
